import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import java.io.BufferedReader;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.io.StringWriter;
import java.nio.charset.Charset;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class WordWrapTest {

    @Mock
    private Reader reader;

    @InjectMocks
    private WordWrap wordWrap;

    @Test
    public void fromReaderBuilder() {
        when(reader.getClass()).thenReturn(StringReader.class);
        assertNotNull(wordWrap.from(reader));
    }

    @Test
    public void fromClasspathUtf8Builder() {
        String resource = "resource";
        File file = new File(resource);
        assertTrue(file.exists());
        wordWrap = WordWrap.fromClasspathUtf8(resource);
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void fromClasspathBuilder() {
        String resource = "resource";
        File file = new File(resource);
        assertTrue(file.exists());
        wordWrap = WordWrap.fromClasspath(resource, StandardCharsets.UTF_8);
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void fromCharSequenceBuilder() {
        String text = "Hello World!";
        wordWrap = WordWrap.from(text);
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void fromUtf8InputStreamBuilder() throws IOException {
        byte[] bytes = "Hello World!".getBytes(StandardCharsets.UTF_8);
        when(reader.read()).thenReturn(bytes.length);
        wordWrap = WordWrap.fromUtf8(new ByteArrayInputStream(bytes));
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void fromInputStreamBuilder() {
        byte[] bytes = "Hello World!".getBytes();
        when(reader.read()).thenReturn(bytes.length);
        wordWrap = WordWrap.from(new ByteArrayInputStream(bytes), StandardCharsets.UTF_8);
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void fromFileBuilder() {
        File file = new File("resource");
        assertTrue(file.exists());
        wordWrap = WordWrap.from(file, StandardCharsets.UTF_8);
        assertNotNull(wordWrap.builder());
    }

    @Test
    public void closeReader() {
        wordWrap = WordWrap.from(reader, false);
        assertEquals(false, wordWrap.close(reader));
    }

    @Test
    public void rightTrimString() {
        String s = "Hello World!";
        when(reader.read()).thenReturn(s.length());
        assertEquals("World!", wordWrap.rightTrim(s));
    }

    @Test
    public void isWhitespaceCharacter() {
        char c = '\t';
        assertTrue(wordWrap.isWhitespace(c));
    }

    @Test
    public void leftTrimStringBuilder() {
        StringBuilder2 word = new StringBuilder2();
        when(reader.read()).thenReturn(0);
        word.leftTrim(word);
        assertEquals("", word.toString());
    }
}

class StringBuilder2 extends StringBuilder {
    private boolean trimmed;

    @Override
    public boolean equals(Object obj) {
        return super.equals(obj) && trimmed;
    }

    void leftTrim(StringBuilder sb) {
        this.trimmed = true;
        sb.replace(0, 0, "");
    }
}
